<?php $pageTitle='Faculty operations';?>
<div class="fp-page"><header class="fp-heading"><div><p class="fp-eyebrow">Coordinator workspace</p><h1>Faculty requests &amp; submissions</h1><p>Review corrections, availability and replacement requests. Decisions are recorded in the audit log.</p></div></header><?php require __DIR__.'/alerts.php';?>
<details class="fp-card"><summary>Reporting and attendance window settings</summary><form class="fp-form fp-form-grid" method="post" action="<?= e(url('faculty-operations/settings')) ?>"><?= csrf_field() ?><?php foreach(['reporting_minutes'=>'Report before exam (minutes)','attendance_before_minutes'=>'Attendance opens before exam (minutes)','attendance_after_minutes'=>'Attendance closes after exam (minutes)'] as $key=>$label):?><label><?= e($label) ?><input type="number" name="<?= e($key) ?>" min="0" max="1440" value="<?= (int)$settings[$key] ?>" required></label><?php endforeach;?><button class="fp-button">Save windows</button></form></details>
<?php foreach(['correction'=>['Attendance correction requests',$corrections],'replacement'=>['Duty replacement requests',$replacements],'availability'=>['Availability requests',$availability]] as $kind=>[$heading,$requests]):?>
<section class="fp-section"><h2><?= e($heading) ?></h2><div class="fp-request-list"><?php foreach($requests as $item):?><article class="fp-card"><div class="fp-card-top"><h3><?= e($item['faculty_name']) ?></h3><span class="fp-status"><?= e(ucfirst($item['status'])) ?></span></div><p><?= e($item['exam_date'].(isset($item['room_code'])?' · Room '.$item['room_code']:' · '.$item['shift_name'].' · '.$item['availability'])) ?></p><p><?= e($item['reason']) ?></p><?php if($item['status']==='pending'):?><form class="fp-review-actions" method="post" action="<?= e(url('faculty-operations/'.$kind.'/'.$item['id'].'/approve')) ?>"><?= csrf_field() ?><?php if($kind==='replacement'):?><label>Replacement faculty<select name="replacement_faculty_id"><option value="">Select an available replacement</option><?php foreach($facultyOptions as $f):?><option value="<?= (int)$f['id'] ?>" <?= (int)($item['replacement_faculty_id']??0)===(int)$f['id']?'selected':'' ?>><?= e($f['employee_id'].' · '.$f['name']) ?></option><?php endforeach;?></select></label><?php endif;?><button class="fp-button">Approve<?= $kind==='correction'?' & reopen attendance':'' ?></button><button class="fp-button fp-secondary" formaction="<?= e(url('faculty-operations/'.$kind.'/'.$item['id'].'/reject')) ?>">Reject</button></form><?php endif;?></article><?php endforeach;?><?php if(!$requests):?><div class="fp-empty">No requests in this category.</div><?php endif;?></div></section><?php endforeach;?></div>
